/**
 * @name colorama: unsafe use of environment variables in os/system calls
 * @description Detects if environment-derived data flows into os.system/popen or subprocess calls.
 * @kind path-problem
 * @problem.severity error
 * @id py/colorama/env-to-command
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module EnvToCmdConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(API::CallNode getenvCall |
      getenvCall = API::moduleImport("os").getMember(["getenv", "environ"]).getACall() and
      source = getenvCall
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode cmdCall |
      cmdCall = API::moduleImport("os").getMember(["system", "popen"]).getACall() and
      sink = cmdCall.getArg(0)
    )
  }
}

module EnvToCmdFlow = TaintTracking::Global<EnvToCmdConfig>;
import EnvToCmdFlow::PathGraph

from EnvToCmdFlow::PathNode source, EnvToCmdFlow::PathNode sink
where EnvToCmdFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Environment data flows into command execution $@.", source.getNode(), "env data"
